def get_serializer_class(self):
    if self.action == 'list':
        return CourseSummarySerializer
    return CourseDetailSerializer

def get_permissions(self):
    if self.action in ['destroy', 'update']:
        return [IsAdminUser()]
    return [AllowAny()]

class ProductCustomViewSet(mixins.CreateModelMixin, mixins.ListModelMixin, viewsets.GenericViewSet):
    queryset = Product.objects.all()
    serializer_class = ProductSerializer

class IsInstructor(BasePermission):
    def has_permission(self, request, view):
        return bool(request.user and request.user.is_authenticated and request.user.role == 'INSTRUCTOR')

class ProductFilter(django_filters.FilterSet):
    min_price = django_filters.NumberFilter(field_name='price', lookup_expr='gte')
    title = django_filters.CharFilter(lookup_expr='icontains')
    class Meta:
        model = Product
        fields = ['min_price', 'title']
